INSERT INTO `dis` VALUES (1,'Coronary Artery Disease','Cholesterol-modifying medications,Aspirin,Beta blockers,Nitroglycerin,Angiotensin-converting enzyme (ACE) inhibitors and angiotensin II receptor blockers (ARBs)','Pain or discomfort in other areas of the upper body including the arms, left shoulder, back, neck, jaw, or stomach','A burning sensation in the chest or upper abdomen','Sweating or cold sweat,Rapid or irregular heart beats','Fullness, indigestion, or choking feeling (may feel like “heartburn”)','http://www.mayoclinic.org/diseases-conditions/coronary-artery-disease/diagnosis-treatment/treatment/txc-20165340'),(2,'Enlarged Heart (Cardiomegaly)','Diuretics,Angiotensin-converting enzyme (ACE) inhibitors,Angiotensin receptor blockers (ARBs),Beta blockers,Digoxin,Anticoagulants,Anti-arrhythmics','Abnormal heart rhythm (arrhythmia)','Swelling (edema)','Severe shortness of breath','Chest Pain','http://www.drugs.com/mcd/enlarged-heart'),(3,'heart attack','Aspirin,Thrombolytics,Antiplatelet agents,Other blood-thinning medications,Pain relievers,Nitroglycerin,Beta blockers,ACE inhibitors','Anxiety, chest pain','Lightheadedness','Upper body pain','Stomach pain','http://www.mayoclinic.org/diseases-conditions/heart-attack/basics/treatment/con-20019520'),(4,'Irregular Heart Rhythm','Amiodarone (Cordarone, Pacerone),Bepridil Hydrochloride (Vascor),Disopyramide (Norpace),Dofetilide (Tikosyn),Dronedarone (Multaq),Flecainide (Tambocor),Ibutilide (Corvert),Lidocaine (Xylocaine),Procainamide (Procan, Procanbid),Propafenone (Rythmol),Propranolol (Inderal),Quinidine (many trade names),Sotalol (Betapace),Tocainide (Tonocarid)','A fluttering in your chest','A racing heartbeat (tachycardia)','A slow heartbeat (bradycardia)','Fainting (syncope) or near fainting','http://www.heart.org/HEARTORG/Conditions/Arrhythmia/PreventionTreatmentofArrhythmia/Medications-for-Arrhythmia_UCM_301990_Article.jsp#'),(5,'Atrial Fibrillation','Beta blockers,Atenolol,Bisoprolol,Carvedilol,Metoprolol,Nadolol,Propranolol,Timolol,Calcium channel blockers,Digoxin,Dilitiazem,Verapamil','Heart palpitations (feeling that your heart is racing or fluttering)','Awareness that the heart is beating.','Fatigue or lack of energy.','Abdominal pain. Exercise intolerance.','http://www.heart.org/HEARTORG/Conditions/Arrhythmia/AboutArrhythmia/Atrial-Fibrillation-Medications_UCM_423781_Article.jsp#.VoNyZ7Z97IU'),(6,'Tool: Heart Rhythm Disorders','Antiarrhythmic drugs,Beta blockers,Calcium channel blockers,Potassium channel blockers,Sodium channel blockers,Anti-clotting agents or anticoagulants (blood thinners),Antihypertensives,Cholesterol-lowering drugs,Diuretics','Fast, steady pulse.','Angina (chest pain)','Heart palpitations.','Fainting (syncope)','http://www.hrsonline.org/Patient-Resources/Treatment/Medications'),(7,'Heart Valve Disease','Ace inhibitors,Anti-arrhythmic medications,Antibiotics,Anticoagulants (\"blood thinners\"),Beta-blockers,Diuretics (\"water pills\"),Vasodilators','Chest pain or palpitations (rapid rhythms or skips)','difficulty catching your breath, weakness, or inability to maintain regular activity level.','loss of consciousness.','Swollen ankles, feet or abdomen.','http://www.heart.org/HEARTORG/Conditions/More/HeartValveProblemsandDisease/Medications-for-Heart-Valve-Symptoms_UCM_450684_Article.jsp#.VoN1LLZ97IU'),(8,'Sudden Cardiac Death','Temporary cardiac pacing,Radiofrequency ablation,Cardioverter defibrillator therapy,Coronary artery bypass grafting (CABG),Excision of ventricular tachycardia foci,Excision of left ventricular aneurysms,Aortic valve replacement,Orthotopic heart transplantation','Sudden collapse','No pulse','No breathing','Loss of consciousness','http://www.mayoclinic.org/diseases-conditions/sudden-cardiac-arrest/diagnosis-treatment/treatment/txc-20164901'),(9,'Congenital Heart Disease','Anti-arrhythmic Drugs,Antibiotics,Anticoagulants,Digoxin,Diuretics,Inotropes,Potassium supplements,Propranolol,Pulmonary vasodilators,Paracetamol,Vasodilators','excessive sweating.','a blue tinge to the skin (cyanosis)','poor feeding.','rapid heartbeat.rapid breathing.','http://www.dhg.org.uk/information/drugs.aspx'),(10,'Heart Muscle Disease (Cardiomyopathy)','Digoxin,Disopyramide,Dobutamine,Encainide Hydrochloride,Flecainide,Fosinopril,Ibutilide,Isoprenaline,Isosorbide Dinitrate and Hydralazine,Milrinone,Moricizine,Nesiritide,Propafenone,Regadenoson','high blood pressure.','particularly during exertion or exercise.','edema, or swelling, of your feet, ankles, and legs.','fainting attacks.','http://www.medindia.net/drugs/medical-condition/cardiomyopathy.htm'),(11,'Dilated Cardiomyopathy','Angiotensin-converting enzyme (ACE) inhibitors,Angiotensin II receptor blockers,Beta blockers,Diuretics,Digoxin,Blood-thinning medications.','Heart failure symptoms (shortness of breath and fatigue).','Swelling of the lower extremities.','Palpitations (fluttering in the chest due to abnormal heart rhythms).','Weight gain.','http://www.mayoclinic.org/diseases-conditions/dilated-cardiomyopathy/basics/treatment/con-20032887'),(12,'Hypertrophic Cardiomyopathy','propranolol oral,Hemangeol oral','occurs usually with exercise or physical activity, but can also occur with rest or after meals','fibrillation or ventricular tachycardia\nSudden death (occurs in a small number of patients with HCM)','Fainting (caused by irregular heart rhythms, abnormal responses of the blood vessels during exercise, or no cause may be found)','Fatique','http://www.webmd.com/drugs/condition-1514-Hypertrophic+Cardiomyopathy.aspx?diseaseid=1514&diseasename=Hypertrophic+Cardiomyopathy&source=0'),(13,'Restrictive Cardiomyopathy ','ACE Inhibitors,Angiotensin II Receptor Blockers (ARBs),Beta Blockers,Calcium Channel Blockers (CCBs),digoxin, Lanoxin,timolol, Blocadren, Timolide 10-25','Swelling of the legs and feet.','Nausea, bloating, and poor appetite (related to fluid retention)','Inability to exercise.','Fainting (usually caused by irregular heart rhythms or abnormal responses of the blood vessels during exercise)','http://www.medicinenet.com/script/main/forum.asp?articlekey=42324&articletype=pharm'),(14,'Pericarditis','Over-the-counter pain relievers,Colchicine (Colcrys),Corticosteroids,Pericardiocentesis,Pericardiectomy','Heart failure symptoms (swelling of legs and feet, unexplained weight gain)','Low-grade fever.','Increased heart rate.','Atrial fibrillation (irregular heartbeat)','http://www.mayoclinic.org/diseases-conditions/pericarditis/basics/treatment/con-20035562'),(15,'Pericardial Effusion','Aspirin,Nonsteroidal anti-inflammatory drugs (NSAIDs), such as indomethacin (Indocin) or ibuprofen (Advil, Motrin IB,others),Colchicine (Colcrys)','Fever','vomiting, and diarrhea (if viral illness is present)','Muscle aches','Cool, clammy skin','http://www.mayoclinic.org/diseases-conditions/pericardial-effusion/basics/treatment/con-20034161'),(16,'Marfan Syndrome','Aorta repair,Scoliosis treatment,Breastbone corrections,Eye surgeries,blood pressure lowering drugs to help prevent the aorta from enlarging and to reduce the risk of dissection and rupture','A tall, thin build.','Long arms, legs, fingers, and toes and flexible joints.','Scoliosis, or curvature of the spine.','A chest that sinks in or sticks out.','http://www.mayoclinic.org/diseases-conditions/marfan-syndrome/basics/treatment/con-20025944'),(17,'Heart Murmurs','Medications that prevent blood clots (anticoagulants),Water pills (diuretics),Angiotensin-converting enzyme (ACE) inhibitors,Statins,Beta blockers.','Skin that appears blue, especially on your fingertips and lips','Poor appetite and failure to grow normally (in infants)','Heavy sweating with minimal or no exertion','Chronic cough','http://www.mayoclinic.org/diseases-conditions/heart-murmurs/basics/treatment/con-20028706');
/*!40000 ALTER TABLE `dis` ENABLE KEYS */;
UNLOCK TABLES;

